CREATE OR REPLACE PROCEDURE DATA_JEDAIS.FINS__PUBLIC.SP_GENERATE_PRODUCT_RECOMMENDATION_INPUTS(MODE STRING DEFAULT 'INPUTS')
RETURNS STRING
LANGUAGE PYTHON
RUNTIME_VERSION = '3.11'
