EXECUTE AS CALLER
AS
$$
from __future__ import annotations

import hashlib

# Inlined from cumulus_common.seed
def seed_for(account_id: str, dataset_salt: str, run_ts: datetime) -> bytes:
    """Return the deterministic 32-byte seed for one (account, dataset, month).

    Args:
        account_id: The Salesforce Account ID, non-empty.
        dataset_salt: Per-dataset salt, e.g. ``"claritas"``, ``"dnb"``. Non-empty.
        run_ts: The execution timestamp; only year/month are used.

    Returns:
        A 32-byte SHA-256 digest. Stable across processes, machines, Python versions.

    Raises:
        ValueError: if ``account_id`` or ``dataset_salt`` is empty.
    """
    if not account_id:
        raise ValueError("account_id must be non-empty")
    if not dataset_salt:
        raise ValueError("dataset_salt must be non-empty")

    key = f"{account_id}|{dataset_salt}|{run_ts:%Y-%m}"
    return hashlib.sha256(key.encode("utf-8")).digest()


# Inlined from cumulus_common.coverage
def assert_coverage(session: Any, expected_sql: str, actual_sql: str) -> None:
    """Verify ``actual_sql`` returns at least ``expected_sql`` rows.

    Args:
        session: A snowflake.snowpark.Session (or duck type with
            ``session.sql(query).collect()`` returning a list of rows).
        expected_sql: A SQL string returning the audience cardinality
            (one int in row 0, column 0).
        actual_sql: A SQL string returning the realized row cardinality
            in the dataset table (one int in row 0, column 0).

    Raises:
        RuntimeError: if ``actual < expected``. Message format is
            ``"coverage gap: <missing> missing rows (expected <e>, got <a>)"``
            so the email taxonomy can filter on the ``"coverage gap:"`` prefix.
    """
    expected = session.sql(expected_sql).collect()[0][0]
    actual = session.sql(actual_sql).collect()[0][0]
    if actual < expected:
        missing = expected - actual
        raise RuntimeError(
            f"coverage gap: {missing} missing rows (expected {expected}, got {actual})"
        )



# ---- prodrec.common ----
import math
import random
from datetime import date, datetime



def stable_rng(key: str, salt: str) -> random.Random:
    """Month-independent RNG: categoricals and base values come from it."""
    return random.Random(seed_for(key, salt, datetime(2026, 1, 1)))


def month_rng(key: str, salt: str, run_ts: datetime) -> random.Random:
    """Per-month RNG: only used for month-to-month drift."""
    return random.Random(seed_for(key, salt + "|month", run_ts))


def jitter(value: float, rng: random.Random, pct: float = 0.03) -> float:
    """value * (1 + U(-pct, pct)); the only month-to-month drift on generated values."""
    return value * (1 + rng.uniform(-pct, pct))


def clamp(v: float, lo: float, hi: float) -> float:
    return max(lo, min(hi, v))


def as_float(v) -> float | None:
    """None/''/non-numeric/NaN -> None; Decimal/int/float/numeric str -> float."""
    if v is None or isinstance(v, bool):
        return None
    if isinstance(v, str):
        v = v.strip()
        if not v:
            return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    return None if math.isnan(f) or math.isinf(f) else f


def as_date(v) -> date | None:
    """date/datetime/ISO 'YYYY-MM-DD...' str -> date; anything else -> None."""
    if v is None:
        return None
    if isinstance(v, datetime):
        return v.date()
    if isinstance(v, date):
        return v
    if isinstance(v, str):
        s = v.strip()[:10]
        try:
            return date.fromisoformat(s)
        except ValueError:
            return None
    return None


def allocate_flags(rates: dict, draws: dict, seeded: dict, target) -> dict:
    """0/1 product flags. `seeded` flags (from real feeds) are kept. Without a real product count the
    rest are drawn at their rates (draws[f] < rate). With one, exactly clamp(target) - sum(seeded) of the
    rest are 1, picked by Efraimidis-Spirakis order (draws[f] ** (1/rate)) so likelier products go first."""
    free = [f for f in rates if f not in seeded]
    flags = {f: int(seeded[f]) for f in rates if f in seeded}
    n = as_float(target)
    if n is None:
        flags.update({f: int(draws[f] < rates[f]) for f in free})
    else:
        on = sum(flags.values())
        k = int(clamp(int(n), on, on + len(free))) - on
        ranked = sorted(free, key=lambda f: draws[f] ** (1.0 / rates[f]), reverse=True)
        flags.update({f: int(f in ranked[:k]) for f in free})
    return {f: flags[f] for f in rates}


