}
REGION_BY_STATE: dict[str, str] = {
    st: region for region, states in _voc_REGION_STATES.items() for st in states.split()
}


def _voc_weighted_pick(weights: dict[str, int], rng: random.Random) -> str:
    return rng.choices(list(weights), weights=list(weights.values()), k=1)[0]


def map_industry(label: str | None, rng: random.Random) -> str:
    """Map an anchor industry label to one of the 14 codes; unknown/blank -> weighted pick."""
    if label is not None:
        hit = _voc_CROSSWALK_LOWER.get(str(label).strip().lower())
        if hit:
            return hit
    return _voc_weighted_pick(INDUSTRY_WEIGHTS, rng)


def map_region(state: str | None, rng: random.Random) -> str:
    """Map a 2-letter state code to a region; unknown/blank -> weighted pick."""
    if state is not None:
        hit = REGION_BY_STATE.get(str(state).strip().upper())
        if hit:
            return hit
    return _voc_weighted_pick(GEOGRAPHIC_REGION_WEIGHTS, rng)


# ---- prodrec.business ----
import math
from datetime import datetime


BUSINESS_SALT = "product_rec_business"

# Cash-flow volatility cut-offs on cv = MONTHLY_NET_SD / max(MONTHLY_CREDITS, 1). Tuned in Task 8.
VOL_LOW_MAX = 0.12
VOL_MED_MAX = 0.24
VOL_MIN_FEED_MONTHS = 2
# Sanity windows (multiples of annual revenue, or of revenue/12 for monthly figures).
DEPOSITS_WINDOW = (0.05, 3.0)      # MONTHLY_CREDITS vs revenue/12
BIZ_BALANCE_WINDOW = (0.01, 2.0)       # DEPOSIT_BALANCE vs revenue
NET_FLOW_WINDOW = (-1.0, 1.0)      # MONTHLY_NET vs revenue/12
BIZ_GEN_DEPOSIT_FRACTION = (0.45, 0.8)  # generated deposits = revenue/12 * U(...)
BIZ_GEN_BALANCE_FRACTION = (0.06, 0.45)  # generated balance = revenue * U(...)
REVENUE_PER_EMPLOYEE = 150_000.0

# Appendix A training ranges (generated values are clamped to these).
_biz_REV_RANGE = (50_000, 50_000_000)
_biz_EMP_RANGE = (1, 370)
_biz_DEP_RANGE = (2_000, 1_524_169)
_biz_NET_RANGE = (-86_309, 176_698)
_biz_BAL_RANGE = (5_500, 4_600_073)
_biz_RATES = {  # Appendix A flag rates
    "HAS_BUSINESS_CHECKING": 0.89, "HAS_BUSINESS_SAVINGS": 0.55,
    "HAS_BUSINESS_CREDIT_CARD": 0.60, "HAS_BUSINESS_LOAN": 0.28,
    "HAS_LINE_OF_CREDIT": 0.24, "HAS_MERCHANT_SERVICES": 0.27,
}
_biz_FLAGS = tuple(_biz_RATES)
_biz_LOCATION_WEIGHTS = {1: 760, 2: 150, 3: 50, 4: 20, 5: 10, 6: 5, 7: 3, 8: 2}
_biz_JITTER_FIELDS = (
    "ANNUAL_REVENUE", "NUMBER_OF_EMPLOYEES", "MONTHLY_AVG_DEPOSITS", "NET_MONTHLY_CASH_FLOW",
    "OPERATING_ACCOUNT_BALANCE", "BUSINESS_CREDIT_SCORE", "DEBT_TO_REVENUE_RATIO",
    "PAYROLL_BURDEN_PCT", "REVENUE_GROWTH_YOY_PCT", "PROFIT_MARGIN_PCT", "AVG_RECEIVABLES_DAYS",
    "DEBT_SERVICE_COVERAGE_RATIO", "MONTHLY_WIRE_TRANSFER_COUNT", "ACH_TRANSACTIONS_PER_EMPLOYEE",
)


def _biz_fin(v: float, lo: float, hi: float, dp: int, factor: float):
    """Jitter by a pre-drawn factor, clamp to the training range, round (dp=0 -> int)."""
    out = round(clamp(v * factor, lo, hi), dp)
    return int(out) if dp == 0 else float(out)


def _biz_in_window(v: float | None, base: float, window: tuple[float, float]) -> bool:
    return v is not None and window[0] * base <= v <= window[1] * base


def _biz_truthy(v) -> bool:
    f = as_float(v)
    return f is not None and f > 0


def _biz_volatility(feats: dict, rng, seasonal: int) -> str:
    sd = as_float(feats.get("MONTHLY_NET_SD"))
    months = as_float(feats.get("FEED_MONTHS"))
    credits = as_float(feats.get("MONTHLY_CREDITS"))
    # Always draw so the rng stream is the same whether or not the feed is used.
    weights = dict(CASH_FLOW_VOLATILITY_WEIGHTS)
    if seasonal:
        weights["High"] *= 2
    drawn = _voc_weighted_pick(weights, rng)
    if sd is not None and months is not None and months >= VOL_MIN_FEED_MONTHS:
        cv = sd / max(credits if credits is not None else 0.0, 1.0)
        if cv <= VOL_LOW_MAX:
            return "Low"
        return "Medium" if cv <= VOL_MED_MAX else "High"
    return drawn


def business_profile(anchor: dict, feats: dict, run_ts: datetime, key: str | None = None) -> dict:
    """Every BUSINESS_TRAINING_COLUMNS key except RECOMMENDED_PRODUCT."""
    account_id = anchor["ACCOUNT_ID"]
    key = key or account_id
    feats = feats or {}
    rng = stable_rng(key, BUSINESS_SALT)
    rng.random()  # industry's own stable_rng consumes one draw when the label is unknown; skip it here
    mrng = month_rng(key, BUSINESS_SALT, run_ts)
    jf = {f: jitter(1.0, mrng) for f in _biz_JITTER_FIELDS}  # fixed order -> stable stream

    industry = map_industry(anchor.get("INDUSTRY"), stable_rng(key, BUSINESS_SALT))

    # --- size (anchor copied, never clamped) --------------------------------------------
    rev_a = as_float(anchor.get("ANNUAL_REVENUE"))
    emp_a = as_float(anchor.get("EMPLOYEE_COUNT"))
    rev_draw = rng.lognormvariate(13.27, 1.27)
    rpe_draw = REVENUE_PER_EMPLOYEE * rng.uniform(0.7, 1.4)
    if rev_a is not None:
        revenue = round(rev_a)
        rev_base = rev_a
    elif emp_a is not None:
        rev_base = max(emp_a, 1.0) * rpe_draw  # scaled from a real anchor: no absolute cap
        revenue = _biz_fin(rev_base, 1, math.inf, 0, jf["ANNUAL_REVENUE"])
    else:
        rev_base = clamp(rev_draw, *_biz_REV_RANGE)
        revenue = _biz_fin(rev_base, *_biz_REV_RANGE, 0, jf["ANNUAL_REVENUE"])
    rev_eff = max(rev_base, 1.0)
    anchored = rev_a is not None or emp_a is not None
    if emp_a is not None:
        employees = round(emp_a)
    elif rev_a is not None:  # derived from a real revenue: min 1, no fixed max
        employees = _biz_fin(rev_eff / rpe_draw, 1, math.inf, 0, jf["NUMBER_OF_EMPLOYEES"])
    else:
        employees = _biz_fin(rev_eff / rpe_draw, *_biz_EMP_RANGE, 0, jf["NUMBER_OF_EMPLOYEES"])
    monthly_rev = rev_eff / 12.0

    # --- profit margin (drives generated cash flow) -------------------------------------
    margin_base = clamp(rng.gauss(11.8, 9.9), -15.0, 40.5)
    margin = _biz_fin(margin_base, -15.0, 40.5, 1, jf["PROFIT_MARGIN_PCT"])

    # --- real-feed-or-generated money values --------------------------------------------
    dep_gen = monthly_rev * rng.uniform(*BIZ_GEN_DEPOSIT_FRACTION)
    bal_gen = rev_eff * rng.uniform(*BIZ_GEN_BALANCE_FRACTION)
    net_gen = margin_base / 100.0 * monthly_rev * rng.uniform(0.8, 1.2)

    # Scale-relative bounds when anchored; absolute Appendix A bounds only when nothing anchors the size.
    if anchored:
        dep_b = (DEPOSITS_WINDOW[0] * monthly_rev, DEPOSITS_WINDOW[1] * monthly_rev)
        bal_b = (BIZ_BALANCE_WINDOW[0] * rev_eff, BIZ_BALANCE_WINDOW[1] * rev_eff)
        net_b = (NET_FLOW_WINDOW[0] * monthly_rev, NET_FLOW_WINDOW[1] * monthly_rev)
    else:
        dep_b, bal_b, net_b = _biz_DEP_RANGE, _biz_BAL_RANGE, _biz_NET_RANGE

    credits = as_float(feats.get("MONTHLY_CREDITS"))
    if _biz_in_window(credits, monthly_rev, DEPOSITS_WINDOW):
        deposits = round(credits)
    else:
        deposits = _biz_fin(dep_gen, *dep_b, 0, jf["MONTHLY_AVG_DEPOSITS"])
    dbal = as_float(feats.get("DEPOSIT_BALANCE"))
    if _biz_in_window(dbal, rev_eff, BIZ_BALANCE_WINDOW):
        balance = round(dbal)
    else:
        balance = _biz_fin(bal_gen, *bal_b, 0, jf["OPERATING_ACCOUNT_BALANCE"])
    net = as_float(feats.get("MONTHLY_NET"))
    if _biz_in_window(net, monthly_rev, NET_FLOW_WINDOW):
        net_flow = round(net)
    else:
        net_flow = _biz_fin(net_gen, *net_b, 0, jf["NET_MONTHLY_CASH_FLOW"])

    # --- categoricals / flags (stable only) ---------------------------------------------
    structure = _voc_weighted_pick(BUSINESS_STRUCTURE_WEIGHTS, rng)
    international = int(rng.random() < 0.09)
    seasonal = int(rng.random() < 0.24)
    digital = _voc_weighted_pick(DIGITAL_BANKING_USAGE_WEIGHTS, rng)
    volatility = _biz_volatility(feats, rng, seasonal)

    draws = {f: rng.random() for f in _biz_FLAGS}  # always drawn, fixed order
    # A feed value (0 or 1) is authoritative; only a missing feed (None) falls back to the draw.
    seeded = {}
    if as_float(feats.get("DEPOSIT_BALANCE")) is not None:  # any FTA deposit account
        seeded["HAS_BUSINESS_CHECKING"] = 1
    elif as_float(feats.get("PRODUCT_COUNT")) is not None:  # FTA-covered, no deposit account
        seeded["HAS_BUSINESS_CHECKING"] = 0
    for feat, flag in (("HAS_LOAN", "HAS_BUSINESS_LOAN"), ("HAS_LINE", "HAS_LINE_OF_CREDIT"),
                       ("HAS_CARD", "HAS_BUSINESS_CREDIT_CARD")):
        if as_float(feats.get(feat)) is not None:
            seeded[flag] = int(_biz_truthy(feats.get(feat)))
    flags = allocate_flags(_biz_RATES, draws, seeded, feats.get("PRODUCT_COUNT"))

    # --- tenure ---------------------------------------------------------------------------
    size_factor = clamp((rev_eff / 1_288_538.0) ** 0.1, 0.6, 1.8)
    yib_gen = int(clamp(round(rng.lognormvariate(1.7, 0.85) * size_factor), 1, 68))
    yac_gen = int(clamp(round(rng.lognormvariate(0.5, 0.9)), 0, 32))
    founded = as_float(feats.get("FOUNDED_YEAR"))
    opened = as_date(feats.get("FIRST_OPEN_DATE"))
    yac_real = max(0, run_ts.year - opened.year) if opened is not None else None
    if founded is not None:
        yib = max(1, run_ts.year - int(founded))
    else:  # a generated age must not contradict a real customer tenure
        yib = max(yib_gen, yac_real or 0)
    yac = yac_real if yac_real is not None else yac_gen
    yac = min(yac, yib)

    locations = _voc_weighted_pick(_biz_LOCATION_WEIGHTS, rng)
    bump = rng.random() < 0.5
    if employees >= 100 and bump:
        locations = min(8, locations + 1)

    # --- training-only continuous variables -----------------------------------------------
    credit = _biz_fin(100 - rng.lognormvariate(0.5, 0.9), 74, 100, 0, jf["BUSINESS_CREDIT_SCORE"])
    d2r = _biz_fin(rng.betavariate(2.5, 8.3), 0.01, 0.69, 2, jf["DEBT_TO_REVENUE_RATIO"])
    payroll = _biz_fin(rng.gauss(35.1, 12.2), 5.0, 75.0, 1, jf["PAYROLL_BURDEN_PCT"])
    growth = _biz_fin(rng.gauss(8.2, 14.7), -30.0, 57.0, 1, jf["REVENUE_GROWTH_YOY_PCT"])
    recv = _biz_fin(rng.gauss(35.0, 14.9), 5, 84, 0, jf["AVG_RECEIVABLES_DAYS"])
    dscr = _biz_fin(rng.gauss(1.8, 0.58), 0.5, 3.79, 2, jf["DEBT_SERVICE_COVERAGE_RATIO"])
    wires = _biz_fin(max(rng.gauss(4.6, 2.7), 0.0), 0, 19, 0, jf["MONTHLY_WIRE_TRANSFER_COUNT"])
    ach = _biz_fin(rng.gauss(3.55, 1.48), 0.5, 9.1, 1, jf["ACH_TRANSACTIONS_PER_EMPLOYEE"])

    profile = {
        "ACCOUNTID": account_id,
        "INDUSTRY": industry,
        "BUSINESS_STRUCTURE": structure,
        "ANNUAL_REVENUE": revenue,
        "NUMBER_OF_EMPLOYEES": employees,
        "YEARS_IN_BUSINESS": yib,
        "MONTHLY_AVG_DEPOSITS": deposits,
        "NET_MONTHLY_CASH_FLOW": net_flow,
        "OPERATING_ACCOUNT_BALANCE": balance,
        "CASH_FLOW_VOLATILITY": volatility,
        "NUMBER_OF_LOCATIONS": locations,
        "INTERNATIONAL_OPERATIONS": international,
        "BUSINESS_CREDIT_SCORE": credit,
        "DEBT_TO_REVENUE_RATIO": d2r,
        "PAYROLL_BURDEN_PCT": payroll,
        **flags,
        "EXISTING_PRODUCT_COUNT": sum(flags.values()),
        "YEARS_AS_CUSTOMER": yac,
        "DIGITAL_BANKING_USAGE": digital,
        "REVENUE_GROWTH_YOY_PCT": growth,
        "PROFIT_MARGIN_PCT": margin,
        "SEASONAL_BUSINESS": seasonal,
        "AVG_RECEIVABLES_DAYS": recv,
        "DEBT_SERVICE_COVERAGE_RATIO": dscr,
        "MONTHLY_WIRE_TRANSFER_COUNT": wires,
        "ACH_TRANSACTIONS_PER_EMPLOYEE": ach,
    }
    return {c: profile[c] for c in BUSINESS_TRAINING_COLUMNS if c != "RECOMMENDED_PRODUCT"}


def business_input_row(profile: dict) -> dict:
    """Project a profile onto the business subset (model input) columns."""
    return {c: profile[c] for c in BUSINESS_SUBSET_COLUMNS}


# ---- prodrec.personal ----
import math
from datetime import datetime


PERSONAL_SALT = "product_rec_personal"

# Sanity windows (multiples of annual income, or of income/12 for monthly figures).
PER_BALANCE_WINDOW = (0.0, 5.0)        # DEPOSIT_BALANCE vs income
DEPOSIT_WINDOW = (0.05, 1.5)       # DIRECT_DEPOSIT / MONTHLY_CREDITS vs income/12
GEN_DEPOSIT_FRACTION = (0.25, 0.6)  # generated deposit = income/12 * U(...)
GEN_BALANCE_FLOOR = 0.01           # generated balance >= 1% of income

# Appendix A training ranges (generated values are clamped to these).
_per_AGE_RANGE = (18, 85)
_per_INC_RANGE = (15_000, 750_000)
_per_CREDIT_RANGE = (450, 850)     # training covers 449-796; real population runs higher
_per_RATES = {  # Appendix A flag rates
    "HAS_CHECKING": 0.90, "HAS_SAVINGS": 0.60, "HAS_INVESTMENT_ACCOUNT": 0.19,
    "HAS_MORTGAGE": 0.35, "HAS_AUTO_LOAN": 0.40, "HAS_CREDIT_CARD": 0.70,
}
_per_MOBILE_RATE = 0.94
# Median generated income by age band (Appendix A mean 55.8k, sd 47.8k -> lognormal sigma 0.7).
_per_INCOME_MEDIAN_BY_AGE = ((25, 24_000), (35, 39_000), (55, 50_000), (65, 43_000), (200, 30_000))
_per_INCOME_SIGMA = 0.7
_per_DEPENDENT_WEIGHTS = (25, 25, 25, 15, 10)
_per_OVERDRAFT_WEIGHTS = (50, 28, 14, 5, 2, 1)
_per_JITTER_FIELDS = (
    "ANNUAL_INCOME", "CREDIT_SCORE", "TOTAL_ACCOUNT_BALANCE", "MONTHLY_DEPOSIT_AMOUNT",
    "DEBT_TO_INCOME_RATIO", "SAVINGS_RATE_PCT", "MONTHLY_TRANSACTION_COUNT",
    "AVG_TRANSACTION_AMOUNT", "DIGITAL_BANKING_LOGINS_MONTHLY", "BRANCH_VISITS_MONTHLY",
    "CUSTOMER_SATISFACTION_SCORE",
)


def _per_fin(v: float, lo: float, hi: float, dp: int, factor: float):
    """Jitter by a pre-drawn factor, clamp, round (dp=0 -> int)."""
    out = round(clamp(v * factor, lo, hi), dp)
    return int(out) if dp == 0 else float(out)


def _per_in_window(v: float | None, base: float, window: tuple[float, float]) -> bool:
    return v is not None and window[0] * base <= v <= window[1] * base


def _per_flag(v) -> int | None:
    """Real 0/1 flag (bool/int/float/'true'/'0'...) -> 0/1; missing -> None."""
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, str) and v.strip().lower() in ("true", "t", "yes", "y"):
        return 1
    if isinstance(v, str) and v.strip().lower() in ("false", "f", "no", "n"):
        return 0
    f = as_float(v)
    return None if f is None else int(f > 0)


def _per_age(birthdate, run_ts: datetime) -> int | None:
    """Age as of the run month's first day, so same-month re-runs agree."""
    b = as_date(birthdate)
    if b is None:
        return None
    d = run_ts.date().replace(day=1)
    return max(0, d.year - b.year - ((d.month, d.day) < (b.month, b.day)))


def _per_scale(weights: dict, factors: dict) -> dict:
    return {k: w * factors.get(k, 1.0) for k, w in weights.items()}


def _per_income_median(age: int) -> float:
    return next((m for hi, m in _per_INCOME_MEDIAN_BY_AGE if age < hi), _per_INCOME_MEDIAN_BY_AGE[-1][1])


def _per_propensity(v) -> float | None:
    """Claritas INVESTMENT_PROPENSITY_SCORE (NUMBER(5,2), 0-100) -> 0..1."""
    f = as_float(v)
    return None if f is None else clamp(f / 100.0, 0.0, 1.0)


def _per_employment_weights(age: int, retirees: bool) -> dict:
    f: dict = {}
    if age < 50:
        f["Retired"] = 0.0
    elif age < 62:
        f["Retired"] = 0.15
    elif age < 70:
        f["Retired"] = 3.0
    else:
        f["Retired"] = 9.0 * sum(w for k, w in EMPLOYMENT_STATUS_WEIGHTS.items()
                                 if k not in ("Retired", "Student")) / EMPLOYMENT_STATUS_WEIGHTS["Retired"]
    if retirees and age >= 50:
        f["Retired"] = f["Retired"] * 3.0 if f["Retired"] > 0 else 0.0
    if age > 35:
        f["Student"] = 0.0
    elif age < 23:
        f["Student"] = 1.5 * sum(w for k, w in EMPLOYMENT_STATUS_WEIGHTS.items()
                                 if k not in ("Retired", "Student")) / EMPLOYMENT_STATUS_WEIGHTS["Student"]
    elif age < 26:
        f["Student"] = 1.0
    else:
        f["Student"] = 0.4
    return _per_scale(EMPLOYMENT_STATUS_WEIGHTS, f)


def _per_education_weights(age: int, income: float) -> dict:
    t = clamp(math.log(max(income, 1.0) / 55_829.0) / math.log(4.0), -1.0, 1.0)
    f = {"Bachelors": 1 + 0.3 * t, "Masters": 1 + 0.8 * t, "Doctorate": 1 + 1.2 * t,
         "High_School": 1 - 0.6 * t, "Associates": 1 - 0.3 * t}
    if age < 22:
        f["Masters"] = f["Doctorate"] = 0.0
    elif age < 26:
        f["Masters"] *= 0.5
        f["Doctorate"] *= 0.1
    return _per_scale(EDUCATION_LEVEL_WEIGHTS, f)


def _per_risk_weights(age: int, propensity: float | None) -> dict:
    f: dict = {}
    if propensity is not None:
        f["Aggressive"] = 0.25 + 1.5 * propensity
        f["Conservative"] = max(0.25, 1.75 - 1.5 * propensity)
    if age >= 65:
        f["Conservative"] = f.get("Conservative", 1.0) * 4.0
        f["Aggressive"] = f.get("Aggressive", 1.0) * 0.3
    return _per_scale(RISK_TOLERANCE_WEIGHTS, f)


def _per_marital_weights(age: int) -> dict:
    f: dict = {}
    if age < 22:
        f.update(Married=0.1, Divorced=0.0, Widowed=0.0)
    elif age < 30:
        f.update(Divorced=0.3, Widowed=0.0)
    elif age >= 65:
        f.update(Widowed=2.0)
    return _per_scale(MARITAL_STATUS_WEIGHTS, f)


def _per_life_event_weights(age: int) -> dict:
    f = {"Retirement_Planning": 0.0 if age < 45 else 2.0 if age >= 55 else 1.0,
         "College_Planning": 0.0 if age >= 50 else 1.0,
         "New_Baby": 1.0 if 20 <= age <= 42 else 0.0,
         "Marriage": 1.0 if age >= 20 else 0.0}
    return _per_scale(RECENT_LIFE_EVENT_WEIGHTS, f)


def personal_profile(anchor: dict, feats: dict, run_ts: datetime, key: str | None = None) -> dict:
    """Every PERSONAL_TRAINING_COLUMNS key except RECOMMENDED_PRODUCT."""
    account_id = anchor["ACCOUNT_ID"]
    key = key or account_id
    feats = feats or {}
    rng = stable_rng(key, PERSONAL_SALT)
    mrng = month_rng(key, PERSONAL_SALT, run_ts)
    jf = {f: jitter(1.0, mrng) for f in _per_JITTER_FIELDS}  # fixed order -> stable stream

    # --- fixed-order base draws (always drawn, used only when the real value is missing) ---
    age_draw = int(clamp(round(rng.gauss(44.6, 14.5)), *_per_AGE_RANGE))
    inc_z = rng.gauss(0.0, 1.0)
    credit_draw = rng.gauss(675.0, 60.0)
    own_draw = _voc_weighted_pick(HOME_OWNERSHIP_WEIGHTS, rng)
    bal_ratio = rng.lognormvariate(-1.3, 0.8)
    dep_frac = rng.uniform(*GEN_DEPOSIT_FRACTION)
    emp_u, edu_u, risk_u, marital_u, life_u = (rng.random() for _ in range(5))
    dependents_u = rng.random()
    flag_u = {f: rng.random() for f in _per_RATES}
    mobile_u = rng.random()
    dti_noise = rng.gauss(0.0, 0.05)
    sav_noise = rng.gauss(0.0, 3.0)
    job_draw = rng.expovariate(1 / 3.0)
    tenure_draw = rng.lognormvariate(1.35, 0.9)
    txn_draw = rng.gauss(24.0, 6.4)
    amt_z = rng.gauss(0.0, 0.8)
    logins_draw = rng.gauss(13.9, 5.5)
    visits_draw = rng.gauss(2.0, 1.4)
    since_draw = rng.lognormvariate(2.4, 1.0)
    csat_draw = rng.gauss(7.46, 1.45)
    overdraft_u = rng.random()

    # --- anchors (copied, never clamped) -------------------------------------------------
    age_a = _per_age(anchor.get("BIRTHDATE"), run_ts)
    age = age_a if age_a is not None else age_draw

    inc_a = as_float(anchor.get("ANNUAL_INCOME"))
    if inc_a is not None:
        income, inc_base = round(inc_a), inc_a
    else:
        inc_base = clamp(_per_income_median(age) * math.exp(_per_INCOME_SIGMA * inc_z), *_per_INC_RANGE)
        income = _per_fin(inc_base, *_per_INC_RANGE, 0, jf["ANNUAL_INCOME"])
    inc_eff = max(inc_base, 1.0)

    cr_a = as_float(anchor.get("CREDIT_SCORE"))
    if cr_a is not None:
        credit, cr_base = round(cr_a), cr_a
    else:
        cr_base = clamp(credit_draw, *_per_CREDIT_RANGE)
        credit = _per_fin(cr_base, *_per_CREDIT_RANGE, 0, jf["CREDIT_SCORE"])

    # --- home ownership (CoreLogic) -------------------------------------------------------
    owner = _per_flag(feats.get("IS_OWNER"))
    mortgage_bal = as_float(feats.get("MORTGAGE_BALANCE"))
    if owner is None:
        home = own_draw
    elif owner:
        home = "Mortgage" if mortgage_bal is not None and mortgage_bal > 0 else "Own"
    else:
        home = "Rent"
    has_mortgage = int(home == "Mortgage")

    region = map_region(anchor.get("STATE_CODE"), stable_rng(key, PERSONAL_SALT + "|region"))

    # --- money: real feed inside the income-relative window, else generated ---------------
    dbal = as_float(feats.get("DEPOSIT_BALANCE"))
    if _per_in_window(dbal, inc_eff, PER_BALANCE_WINDOW):
        bal_base, balance = dbal, round(dbal)
    else:
        bal_base = clamp(bal_ratio * inc_eff, GEN_BALANCE_FLOOR * inc_eff, PER_BALANCE_WINDOW[1] * inc_eff)
        balance = _per_fin(bal_base, GEN_BALANCE_FLOOR * inc_eff, PER_BALANCE_WINDOW[1] * inc_eff, 0,
                           jf["TOTAL_ACCOUNT_BALANCE"])
    monthly_inc = inc_eff / 12.0
    deposit = None
    for feed in ("DIRECT_DEPOSIT", "MONTHLY_CREDITS"):
        v = as_float(feats.get(feed))
        if _per_in_window(v, monthly_inc, DEPOSIT_WINDOW):
            deposit = round(v)
            break
    if deposit is None:
        deposit = _per_fin(dep_frac * monthly_inc, DEPOSIT_WINDOW[0] * monthly_inc,
                           DEPOSIT_WINDOW[1] * monthly_inc, 0, jf["MONTHLY_DEPOSIT_AMOUNT"])

    # --- categoricals (stable only) -------------------------------------------------------
    retirees = str(feats.get("LIFE_STAGE") or "").strip().lower() == "retirees"
    employment = _per_pick_u(_per_employment_weights(age, retirees), emp_u)
    education = _per_pick_u(_per_education_weights(age, inc_eff), edu_u)
    risk = _per_pick_u(_per_risk_weights(age, _per_propensity(feats.get("INVESTMENT_PROPENSITY"))), risk_u)
    marital = _per_pick_u(_per_marital_weights(age), marital_u)
    life_event = _per_pick_u(_per_life_event_weights(age), life_u)
    dep_w = [0.0 if (age < 22 and i > 0) or (age < 25 and i > 1) else w
             for i, w in enumerate(_per_DEPENDENT_WEIGHTS)]
    dependents = int(_per_pick_u({i: w for i, w in enumerate(dep_w)}, dependents_u))

    # --- ratios from un-jittered bases ----------------------------------------------------
    cr_eff = clamp(cr_base, 300.0, 850.0)
    dti_base = 0.48 - (cr_eff - 300.0) / 550.0 * 0.40 + dti_noise + (0.08 if has_mortgage else 0.0)
    dti = _per_fin(clamp(dti_base, 0.0, 0.68), 0.0, 0.68, 2, jf["DEBT_TO_INCOME_RATIO"])
    sav_base = 3.0 + 14.0 * math.sqrt(max(bal_base, 0.0) / inc_eff) + sav_noise
    savings_rate = _per_fin(clamp(sav_base, 0.1, 36.1), 0.1, 36.1, 1, jf["SAVINGS_RATE_PCT"])

    # --- holdings -------------------------------------------------------------------------
    seeded = {"HAS_MORTGAGE": has_mortgage}
    if dbal is not None:  # any deposit account in the feed
        seeded["HAS_CHECKING"] = 1
    elif as_float(feats.get("PRODUCT_COUNT")) is not None:  # FTA-covered, no deposit account
        seeded["HAS_CHECKING"] = 0
    for feat, flag in (("HAS_INVESTMENT", "HAS_INVESTMENT_ACCOUNT"), ("HAS_CARD", "HAS_CREDIT_CARD")):
        real = _per_flag(feats.get(feat))
        if real is not None:  # a real 0 is information; draw only when missing
            seeded[flag] = real
    if _per_flag(feats.get("HAS_LOAN")) == 0:  # no loan at all rules out an auto loan; 1 does not seed it
        seeded["HAS_AUTO_LOAN"] = 0
    ordered = allocate_flags(_per_RATES, flag_u, seeded, feats.get("PRODUCT_COUNT"))

    # --- tenure / job ---------------------------------------------------------------------
    adult_years = max(0, age - 18)
    opened = as_date(feats.get("FIRST_OPEN_DATE"))
    tenure = max(0, run_ts.year - opened.year) if opened is not None else int(clamp(round(tenure_draw), 0, 40))
    tenure = min(tenure, adult_years)
    job = 0 if employment in ("Student", "Unemployed") else int(clamp(round(job_draw), 0, 37))
    job = min(job, adult_years)

    # --- training-only behaviour ----------------------------------------------------------
    txn_count = _per_fin(txn_draw, 3, 47, 0, jf["MONTHLY_TRANSACTION_COUNT"])
    amt_median = 147.0 * (inc_eff / 55_829.0) ** 0.3
    avg_amt = _per_fin(amt_median * math.exp(amt_z), 10, 2817, 0, jf["AVG_TRANSACTION_AMOUNT"])
    mobile = int(mobile_u < _per_MOBILE_RATE)
    logins = _per_fin(logins_draw, 0, 32, 0, jf["DIGITAL_BANKING_LOGINS_MONTHLY"])
    visits = _per_fin(visits_draw, 0, 9, 0, jf["BRANCH_VISITS_MONTHLY"])
    since = int(clamp(round(since_draw), 1, 120))
    csat = _per_fin(csat_draw, 1.5, 10.0, 1, jf["CUSTOMER_SATISFACTION_SCORE"])
    overdraft = int(_per_pick_u(dict(enumerate(_per_OVERDRAFT_WEIGHTS)), overdraft_u))

    profile = {
        "ACCOUNTID": account_id,
        "AGE": age,
        "EDUCATION_LEVEL": education,
        "ANNUAL_INCOME": income,
        "CREDIT_SCORE": credit,
        "EMPLOYMENT_STATUS": employment,
        "YEARS_AT_CURRENT_JOB": job,
        "MARITAL_STATUS": marital,
        "NUMBER_OF_DEPENDENTS": dependents,
        "HOME_OWNERSHIP": home,
        "GEOGRAPHIC_REGION": region,
        "TOTAL_ACCOUNT_BALANCE": balance,
        "MONTHLY_TRANSACTION_COUNT": txn_count,
        "AVG_TRANSACTION_AMOUNT": avg_amt,
        "MONTHLY_DEPOSIT_AMOUNT": deposit,
        "DEBT_TO_INCOME_RATIO": dti,
        **ordered,
        "EXISTING_PRODUCT_COUNT": sum(ordered.values()),
        "YEARS_AS_CUSTOMER": tenure,
        "DIGITAL_BANKING_LOGINS_MONTHLY": logins,
        "BRANCH_VISITS_MONTHLY": visits,
        "MOBILE_APP_ACTIVE": mobile,
        "RISK_TOLERANCE": risk,
        "RECENT_LIFE_EVENT": life_event,
        "MONTHS_SINCE_LAST_PRODUCT": since,
        "CUSTOMER_SATISFACTION_SCORE": csat,
        "OVERDRAFT_COUNT_12M": overdraft,
        "SAVINGS_RATE_PCT": savings_rate,
    }
    return {c: profile[c] for c in PERSONAL_TRAINING_COLUMNS if c != "RECOMMENDED_PRODUCT"}


def _per_pick_u(weights: dict, u: float):
    """Weighted pick from a pre-drawn uniform u in [0, 1) so the rng stream never depends on weights."""
    total = sum(weights.values())
    target, acc, last = u * total, 0.0, None
    for k, w in weights.items():
        if w <= 0:
            continue
        last = k
        acc += w
        if target < acc:
            return k
    return last


def personal_input_row(profile: dict) -> dict:
    """Project a profile onto the personal subset (model input) columns."""
    return {c: profile[c] for c in PERSONAL_SUBSET_COLUMNS}


# ---- prodrec.labels ----
BASE_SCORE = 0.05
NOISE = 0.35

# --- Business terms ------------------------------------------------------------------------
_lbl_LOC_HIGH_VOL = 0.95           # High volatility, no line of credit
_lbl_LOC_SEASONAL = 0.3            # seasonal, no line of credit
_lbl_LOC_MED_VOL = 0.15            # Medium volatility, no line of credit
_lbl_TRS_REV_HUGE, _lbl_TRS_REV_HUGE_W = 50_000_000, 1.0
_lbl_TRS_REV_LARGE, _lbl_TRS_REV_LARGE_W = 20_000_000, 0.5
_lbl_TRS_LOCATIONS, _lbl_TRS_LOCATIONS_W = 5, 0.6
_lbl_TRS_WIRES, _lbl_TRS_WIRES_W = 10, 0.2
_lbl_TRS_INTL_W = 0.2
_lbl_MERCHANT_INDUSTRIES = ("Retail", "Food_Beverage", "Hospitality")
_lbl_MERCHANT_W = 1.0
_lbl_IDLE_START, _lbl_IDLE_SPAN, _lbl_IDLE_W = 0.25, 0.25, 0.9   # balance / revenue ramp
_lbl_IDLE_MM_LOW_VOL, _lbl_IDLE_CD_LOW_VOL, _lbl_IDLE_CD_OTHER = 0.9, 1.0, 0.5
_lbl_LOAN_INDUSTRIES = ("Construction", "Manufacturing", "Real_Estate")
_lbl_LOAN_INDUSTRY_W = 0.4
_lbl_LOAN_GROWTH, _lbl_LOAN_GROWTH_W = 15.0, 0.5
_lbl_LOAN_DSCR, _lbl_LOAN_DSCR_W = 1.5, 0.4     # only counts when growth also qualifies
_lbl_YOUNG_YEARS = 3
_lbl_THIN_COUNT = 1
_lbl_CC_YOUNG_W, _lbl_CC_THIN_W, _lbl_CC_NO_CARD_W = 0.5, 0.5, 0.3
_lbl_BBS_YOUNG_W, _lbl_BBS_THIN_W, _lbl_BBS_NO_CHECKING_W = 0.4, 0.5, 0.6
_lbl_WM_REV, _lbl_WM_BAL, _lbl_WM_YEARS = 10_000_000, 1_000_000, 10
_lbl_WM_W = 0.4                                  # per condition
_lbl_BA_BAL, _lbl_BA_BAL_W = 500_000, 0.6
_lbl_BA_MARGIN, _lbl_BA_MARGIN_W = 20.0, 0.4
_lbl_BA_YEARS, _lbl_BA_YEARS_W = 8, 0.2
_lbl_SAV_NO_SAVINGS_POS_FLOW, _lbl_SAV_NO_SAVINGS = 0.9, 0.3
_lbl_DEP_NO_SAVINGS_POS_FLOW = 0.7
_lbl_DEP_LOW_VOL_DEPOSITS, _lbl_DEP_DEPOSIT_RATIO = 0.7, 0.9   # deposits >= ratio * revenue/12

# --- Personal terms ------------------------------------------------------------------------
_lbl_P_SAVE_RATE = 12.0
_lbl_P_SAV_RATE_W, _lbl_P_SAV_RENT_W, _lbl_P_SAV_NO_SAVINGS_W = 0.5, 0.4, 0.3
_lbl_P_CD_RATE_W, _lbl_P_CD_RENT_W, _lbl_P_CD_CONS_W = 0.3, 0.4, 0.3
_lbl_P_CD_CONS_BAL = 20_000
_lbl_P_HELOC_CREDIT, _lbl_P_HELOC_CREDIT_W = 740, 0.5
_lbl_P_HELOC_MORTGAGE_W = 0.4
_lbl_P_EQUITY_AGE, _lbl_P_EQUITY_DTI, _lbl_P_EQUITY_W = 35, 0.35, 0.5   # proxy for property equity
_lbl_P_RES_RENT_W, _lbl_P_RES_CREDIT, _lbl_P_RES_CREDIT_W = 0.4, 720, 0.4
_lbl_P_RES_INCOME, _lbl_P_RES_INCOME_W = 80_000, 0.5
_lbl_P_PL_CREDIT, _lbl_P_PL_CREDIT_W = 670, 0.3
_lbl_P_PL_DTI, _lbl_P_PL_DTI_W, _lbl_P_PL_BOTH_W = 0.33, 0.6, 0.3
_lbl_P_AUTO_NO_LOAN_W = 0.3
_lbl_P_AUTO_AGE, _lbl_P_AUTO_AGE_W = (22, 60), 0.3
_lbl_P_AUTO_EMP_FT_W, _lbl_P_AUTO_EMP_OTHER_W = 0.4, 0.2
_lbl_P_BA_BAL, _lbl_P_BA_AGGRESSIVE_W, _lbl_P_BA_NONCONS_W = 100_000, 0.8, 0.3
_lbl_P_WM_INCOME, _lbl_P_WM_INCOME_W = 250_000, 0.7
_lbl_P_WM_AGE, _lbl_P_WM_AGE_W = 50, 0.4
_lbl_P_WM_BAL, _lbl_P_WM_BAL_W = 500_000, 0.5
_lbl_P_CC_AGE, _lbl_P_CC_AGE_W = 25, 0.5
_lbl_P_CC_THIN_COUNT, _lbl_P_CC_THIN_W, _lbl_P_CC_NO_CARD_W = 1, 0.6, 0.3
_lbl_P_MM_BAL, _lbl_P_MM_DTI, _lbl_P_MM_W = 50_000, 0.3, 0.8
_lbl_P_DEP_NO_CHECKING_W = 0.8
_lbl_P_DEP_BAL, _lbl_P_DEP_BAL_W = 30_000, 0.4


def _lbl_f(p: dict, key: str, default: float = 0.0) -> float:
    v = p.get(key)
    return default if v is None else float(v)


def _lbl_flag(p: dict, key: str) -> bool:
    return _lbl_f(p, key) > 0


def business_scores(p: dict) -> dict[str, float]:
    """Score every business class; each score is BASE_SCORE plus its additive rule terms."""
    s = {c: BASE_SCORE for c in BUSINESS_PRODUCTS}
    rev = max(_lbl_f(p, "ANNUAL_REVENUE"), 1.0)
    bal = _lbl_f(p, "OPERATING_ACCOUNT_BALANCE")
    vol = p.get("CASH_FLOW_VOLATILITY")
    industry = p.get("INDUSTRY")
    net = _lbl_f(p, "NET_MONTHLY_CASH_FLOW")
    yib = _lbl_f(p, "YEARS_IN_BUSINESS")
    yac = _lbl_f(p, "YEARS_AS_CUSTOMER")
    count = _lbl_f(p, "EXISTING_PRODUCT_COUNT")
    no_loc = not _lbl_flag(p, "HAS_LINE_OF_CREDIT")
    no_savings = not _lbl_flag(p, "HAS_BUSINESS_SAVINGS")

    if no_loc:
        if vol == "High":
            s["Line_of_Credit"] += _lbl_LOC_HIGH_VOL
        elif vol == "Medium":
            s["Line_of_Credit"] += _lbl_LOC_MED_VOL
        if _lbl_flag(p, "SEASONAL_BUSINESS"):
            s["Line_of_Credit"] += _lbl_LOC_SEASONAL

    if rev >= _lbl_TRS_REV_HUGE:
        s["Treasury_Services"] += _lbl_TRS_REV_HUGE_W
    elif rev >= _lbl_TRS_REV_LARGE:
        s["Treasury_Services"] += _lbl_TRS_REV_LARGE_W
    if _lbl_f(p, "NUMBER_OF_LOCATIONS") >= _lbl_TRS_LOCATIONS:
        s["Treasury_Services"] += _lbl_TRS_LOCATIONS_W
    if _lbl_f(p, "MONTHLY_WIRE_TRANSFER_COUNT") >= _lbl_TRS_WIRES:
        s["Treasury_Services"] += _lbl_TRS_WIRES_W
    if _lbl_flag(p, "INTERNATIONAL_OPERATIONS"):
        s["Treasury_Services"] += _lbl_TRS_INTL_W

    if industry in _lbl_MERCHANT_INDUSTRIES and not _lbl_flag(p, "HAS_MERCHANT_SERVICES"):
        s["Merchant_Services"] += _lbl_MERCHANT_W

    idle = clamp((bal / rev - _lbl_IDLE_START) / _lbl_IDLE_SPAN, 0.0, 1.0) * _lbl_IDLE_W
    low_vol = vol == "Low"
    s["Money_Market"] += idle * (_lbl_IDLE_MM_LOW_VOL if low_vol else 1.0)
    s["CDs"] += idle * (_lbl_IDLE_CD_LOW_VOL if low_vol else _lbl_IDLE_CD_OTHER)

    growth_ok = _lbl_f(p, "REVENUE_GROWTH_YOY_PCT") >= _lbl_LOAN_GROWTH
    if industry in _lbl_LOAN_INDUSTRIES:
        s["Commercial_Loans"] += _lbl_LOAN_INDUSTRY_W
    if growth_ok:
        s["Commercial_Loans"] += _lbl_LOAN_GROWTH_W
        if _lbl_f(p, "DEBT_SERVICE_COVERAGE_RATIO") >= _lbl_LOAN_DSCR:
            s["Commercial_Loans"] += _lbl_LOAN_DSCR_W

    young = yib <= _lbl_YOUNG_YEARS
    thin = count <= _lbl_THIN_COUNT
    if young:
        s["Credit_Cards"] += _lbl_CC_YOUNG_W
        s["Business_Banking_Services"] += _lbl_BBS_YOUNG_W
    if thin:
        s["Credit_Cards"] += _lbl_CC_THIN_W
        s["Business_Banking_Services"] += _lbl_BBS_THIN_W
    if not _lbl_flag(p, "HAS_BUSINESS_CREDIT_CARD"):
        s["Credit_Cards"] += _lbl_CC_NO_CARD_W
    if not _lbl_flag(p, "HAS_BUSINESS_CHECKING"):
        s["Business_Banking_Services"] += _lbl_BBS_NO_CHECKING_W

    s["Wealth_Management"] += _lbl_WM_W * (
        (rev >= _lbl_WM_REV) + (bal >= _lbl_WM_BAL) + (yac >= _lbl_WM_YEARS))
    if bal >= _lbl_BA_BAL:
        s["Brokerage_Advisory"] += _lbl_BA_BAL_W
    if _lbl_f(p, "PROFIT_MARGIN_PCT") >= _lbl_BA_MARGIN:
        s["Brokerage_Advisory"] += _lbl_BA_MARGIN_W
    if yac >= _lbl_BA_YEARS:
        s["Brokerage_Advisory"] += _lbl_BA_YEARS_W

    if no_savings:
        s["Savings"] += _lbl_SAV_NO_SAVINGS_POS_FLOW if net > 0 else _lbl_SAV_NO_SAVINGS
        if net > 0:
            s["Deposits"] += _lbl_DEP_NO_SAVINGS_POS_FLOW
    if (low_vol and _lbl_f(p, "MONTHLY_AVG_DEPOSITS") >= _lbl_DEP_DEPOSIT_RATIO * rev / 12.0
            and idle == 0.0):
        s["Deposits"] += _lbl_DEP_LOW_VOL_DEPOSITS
    return s


def personal_scores(p: dict) -> dict[str, float]:
    """Score every personal class; each score is BASE_SCORE plus its additive rule terms."""
    s = {c: BASE_SCORE for c in PERSONAL_PRODUCTS}
    age = _lbl_f(p, "AGE")
    income = _lbl_f(p, "ANNUAL_INCOME")
    credit = _lbl_f(p, "CREDIT_SCORE")
    bal = _lbl_f(p, "TOTAL_ACCOUNT_BALANCE")
    dti = _lbl_f(p, "DEBT_TO_INCOME_RATIO")
    rate = _lbl_f(p, "SAVINGS_RATE_PCT")
    home = p.get("HOME_OWNERSHIP")
    risk = p.get("RISK_TOLERANCE")
    employment = p.get("EMPLOYMENT_STATUS")
    count = _lbl_f(p, "EXISTING_PRODUCT_COUNT")
    rent = home == "Rent"
    high_rate = rate >= _lbl_P_SAVE_RATE

    if high_rate:
        s["Savings"] += _lbl_P_SAV_RATE_W
        s["CDs"] += _lbl_P_CD_RATE_W
        if rent:
            s["Savings"] += _lbl_P_SAV_RENT_W
            s["CDs"] += _lbl_P_CD_RENT_W
    if not _lbl_flag(p, "HAS_SAVINGS"):
        s["Savings"] += _lbl_P_SAV_NO_SAVINGS_W
    if risk == "Conservative" and bal >= _lbl_P_CD_CONS_BAL:
        s["CDs"] += _lbl_P_CD_CONS_W

    if credit >= _lbl_P_HELOC_CREDIT:
        s["HELOC"] += _lbl_P_HELOC_CREDIT_W
    if home == "Mortgage":
        s["HELOC"] += _lbl_P_HELOC_MORTGAGE_W
        if age >= _lbl_P_EQUITY_AGE and dti <= _lbl_P_EQUITY_DTI:
            s["HELOC"] += _lbl_P_EQUITY_W

    if rent:
        s["Residential_Loans"] += _lbl_P_RES_RENT_W
        if credit >= _lbl_P_RES_CREDIT:
            s["Residential_Loans"] += _lbl_P_RES_CREDIT_W
        if income >= _lbl_P_RES_INCOME:
            s["Residential_Loans"] += _lbl_P_RES_INCOME_W

    mid_credit = credit <= _lbl_P_PL_CREDIT
    high_dti = dti >= _lbl_P_PL_DTI
    s["Personal_Loans"] += (_lbl_P_PL_CREDIT_W * mid_credit + _lbl_P_PL_DTI_W * high_dti
                            + _lbl_P_PL_BOTH_W * (mid_credit and high_dti))

    if not _lbl_flag(p, "HAS_AUTO_LOAN"):
        s["Auto_Loans"] += _lbl_P_AUTO_NO_LOAN_W
        if _lbl_P_AUTO_AGE[0] <= age <= _lbl_P_AUTO_AGE[1]:
            s["Auto_Loans"] += _lbl_P_AUTO_AGE_W
        if employment == "Employed_FT":
            s["Auto_Loans"] += _lbl_P_AUTO_EMP_FT_W
        elif employment in ("Employed_PT", "Self_Employed"):
            s["Auto_Loans"] += _lbl_P_AUTO_EMP_OTHER_W

    if bal >= _lbl_P_BA_BAL:
        if risk == "Aggressive":
            s["Brokerage_Advisory"] += _lbl_P_BA_AGGRESSIVE_W
        if risk != "Conservative":
            s["Brokerage_Advisory"] += _lbl_P_BA_NONCONS_W

    if income >= _lbl_P_WM_INCOME:
        s["Wealth_Management"] += _lbl_P_WM_INCOME_W
    if age >= _lbl_P_WM_AGE:
        s["Wealth_Management"] += _lbl_P_WM_AGE_W
    if bal >= _lbl_P_WM_BAL:
        s["Wealth_Management"] += _lbl_P_WM_BAL_W

    if age <= _lbl_P_CC_AGE:
        s["Credit_Cards"] += _lbl_P_CC_AGE_W
    if count <= _lbl_P_CC_THIN_COUNT:
        s["Credit_Cards"] += _lbl_P_CC_THIN_W
    if not _lbl_flag(p, "HAS_CREDIT_CARD"):
        s["Credit_Cards"] += _lbl_P_CC_NO_CARD_W

    if bal >= _lbl_P_MM_BAL and dti < _lbl_P_MM_DTI:
        s["Money_Market"] += _lbl_P_MM_W
    if not _lbl_flag(p, "HAS_CHECKING"):
        s["Deposits"] += _lbl_P_DEP_NO_CHECKING_W
    if bal >= _lbl_P_DEP_BAL and dti < _lbl_P_MM_DTI:
        s["Deposits"] += _lbl_P_DEP_BAL_W
    return s


def rule_label(scores: dict[str, float]) -> str:
    """Argmax of the scores; ties go to the earliest class in dict (tuple) order."""
    best, best_score = None, float("-inf")
    for c, v in scores.items():
        if v > best_score:
            best, best_score = c, v
    return best


def draw_label(scores: dict[str, float], rng, noise: float = NOISE) -> str:
    """rule_label with probability 1 - noise, else a draw weighted by the scores."""
    if rng.random() >= noise:
        return rule_label(scores)
    total = sum(scores.values())
    pick = rng.random() * total
    acc = 0.0
    last = None
    for c, v in scores.items():
        acc += v
        last = c
        if pick < acc:
            return c
    return last


# ---- prodrec.training ----
from collections import Counter
from datetime import datetime
from typing import Literal



def _trn_side(side: str):
    if side == "business":
        return business_profile, business_scores, BUSINESS_PRODUCTS, BUSINESS_TRAINING_COLUMNS, "B"
    if side == "personal":
        return personal_profile, personal_scores, PERSONAL_PRODUCTS, PERSONAL_TRAINING_COLUMNS, "P"
    raise ValueError(f"unknown side: {side!r}")


def build_training_set(
    population: list[tuple[dict, dict]],
    side: Literal["business", "personal"],
    run_ts: datetime,
    size: int,
    floor: int = 100,
) -> list[dict]:
    profile_fn, scores_fn, products, columns, prefix = _trn_side(side)
    if not population:
        raise ValueError("empty population")
    if size < 1:
        raise ValueError("size must be >= 1")
    month = f"{run_ts:%Y-%m}"
    # Draws index into the population, so fix its order: same accounts -> same set, any input order.
    population = sorted(population, key=lambda p: str(p[0]["ACCOUNT_ID"]))

    pool_rng = stable_rng(f"pool|{month}", side + "_training")
    pool: list[tuple[dict, str]] = []
    for i in range(3 * size):
        anchor, feats = population[pool_rng.randrange(len(population))]
        key = f"{anchor['ACCOUNT_ID']}#T{i}"
        profile = profile_fn(anchor, feats, run_ts, key=key)
        label = draw_label(scores_fn(profile), stable_rng(f"{key}|{month}", side + "_label"))
        pool.append((profile, label))

    taken: set[int] = set()
    for cls in products:
        n = 0
        for idx, (_, label) in enumerate(pool):
            if n >= floor or len(taken) >= size:
                break
            if label == cls and idx not in taken:
                taken.add(idx)
                n += 1
    for idx in range(len(pool)):
        if len(taken) >= size:
            break
        taken.add(idx)

    chosen = [pool[i] for i in sorted(taken)]
    stable_rng(f"shuffle|{month}", side + "_training").shuffle(chosen)

    rows = []
    for n, (profile, label) in enumerate(chosen, start=1):
        row = dict(profile)
        row["RECOMMENDED_PRODUCT"] = label
        row["ACCOUNTID"] = f"{prefix}-{n:06d}"
        rows.append({c: row[c] for c in columns})
    return rows


def mix_problems(
    labels: list[str],
    max_share: float = 0.40,
    min_classes: int = 8,
    floor: int | None = None,
) -> list[str]:
    counts = Counter(labels)
    total = len(labels)
    problems = []
    for cls, n in sorted(counts.items()):
        if total and n / total > max_share:
            problems.append(f"max share exceeded: {cls} is {n / total:.1%} (limit {max_share:.0%})")
    if len(counts) < min_classes:
        problems.append(f"classes: only {len(counts)} distinct (need at least {min_classes})")
    if floor is not None:
        for cls, n in sorted(counts.items()):
            if n < floor:
                problems.append(f"floor not met: {cls} has {n} rows (need at least {floor})")
    return problems


# ---- prodrec.sp_main ----
import uuid
from datetime import datetime, timezone


TASK_NAME = "TASK_MONTHLY_PRODUCT_RECOMMENDATION_INPUTS"

_sp_DB = "DATA_JEDAIS"
_sp_SCHEMA = "FINS__PUBLIC"
_sp_PREFIX = f"{_sp_DB}.{_sp_SCHEMA}"
_sp_BIZ_SUBSET = f"{_sp_PREFIX}.BUSINESS_PRODUCT_RECOMMENDATION_SUBSET"
_sp_PER_SUBSET = f"{_sp_PREFIX}.PERSONAL_PRODUCT_RECOMMENDATION_SUBSET"
_sp_BIZ_TRAINING = f"{_sp_PREFIX}.BUSINESS_PRODUCT_RECOMMENDATION_SET"
_sp_PER_TRAINING = f"{_sp_PREFIX}.PERSONAL_PRODUCT_RECOMMENDATION_TRAINING_SET"
_sp_BIZ_TRAINING_SIZE = 3500
_sp_PER_TRAINING_SIZE = 7500
_sp_MODES = ("INPUTS", "TRAINING", "ALL")

# Audience CTEs, written once per side; the feature SQL and the live recount share them.
_sp_BIZ_AUD = f"""aud AS (
  SELECT * FROM {_sp_PREFIX}.V_ACCOUNT_ANCHORS
  WHERE ACCOUNT_TYPE_FLAG = 'BUSINESS' AND COALESCE(CLIENT_CATEGORY, '') <> 'Household' AND ACCOUNT_ID LIKE '001am%'
  QUALIFY ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID ORDER BY ANNUAL_REVENUE DESC NULLS LAST, EMPLOYEE_COUNT DESC NULLS LAST) = 1
)"""
_sp_PER_AUD = f"""aud AS (
  SELECT * FROM {_sp_PREFIX}.V_ACCOUNT_ANCHORS
  WHERE ACCOUNT_TYPE_FLAG = 'PERSON'
  QUALIFY ROW_NUMBER() OVER (PARTITION BY ACCOUNT_ID ORDER BY ANNUAL_INCOME DESC NULLS LAST) = 1
)"""

# Feed windows end at the run month's first day (exclusive), so every re-run inside a month
# reads the same 90 days and in-month / future-dated transactions never enter.
_sp_FEED_ANCHOR = "DATE_TRUNC('month', CURRENT_DATE())"
_sp_FEED_WINDOW = (
    f"TRANSACTIONDATE >= DATEADD(day, -90, {_sp_FEED_ANCHOR}) AND TRANSACTIONDATE < {_sp_FEED_ANCHOR}"
)

BUSINESS_FEATURES_SQL = f"""WITH {_sp_BIZ_AUD},
fta AS (
  SELECT SFACCOUNTID AS ACCOUNT_ID,
         SUM(IFF(PRODUCT_KIND = 'deposit', BALANCE, NULL)) AS DEPOSIT_BALANCE,
         COUNT(DISTINCT FINANCIAL_ACCOUNT_TYPE) AS PRODUCT_COUNT, MIN(OPEN_DATE) AS FIRST_OPEN_DATE,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Loans' AND PRODUCT_KIND = 'loan', 1, 0)) AS HAS_LOAN,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Loans' AND PRODUCT_KIND = 'line', 1, 0)) AS HAS_LINE,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Credit Cards', 1, 0)) AS HAS_CARD,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Treasury Management', 1, 0)) AS HAS_TREASURY,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Investments', 1, 0)) AS HAS_INVESTMENT
  FROM {_sp_PREFIX}.FINANCIAL_TRANSACTION_ACCOUNTS
  WHERE COALESCE(ACTIVE, TRUE) GROUP BY 1
),
ftm AS (
  SELECT SFACCOUNTID AS ACCOUNT_ID, FLOOR(DATEDIFF(day, TRANSACTIONDATE, {_sp_FEED_ANCHOR}) / 30) AS b,
         SUM(IFF(TRANSACTION_TYPE = 'Credit', AMOUNT, 0)) AS cr, SUM(IFF(TRANSACTION_TYPE = 'Debit', AMOUNT, 0)) AS dr
  FROM {_sp_PREFIX}.FINANCIAL_TRANSACTIONS
  WHERE {_sp_FEED_WINDOW} GROUP BY 1, 2
),
ft AS (
  SELECT ACCOUNT_ID, AVG(cr) AS MONTHLY_CREDITS, AVG(cr - dr) AS MONTHLY_NET,
         STDDEV_POP(cr - dr) AS MONTHLY_NET_SD, COUNT(*) AS FEED_MONTHS
  FROM ftm WHERE b < 3 GROUP BY 1
),
zi AS (
  SELECT ACCOUNT_ID, MAX(FOUNDED_YEAR) AS FOUNDED_YEAR FROM {_sp_PREFIX}.ZOOMINFO_FIRMOGRAPHICS
  WHERE PROFILE_MONTH = (SELECT MAX(PROFILE_MONTH) FROM {_sp_PREFIX}.ZOOMINFO_FIRMOGRAPHICS) GROUP BY 1
)
SELECT aud.*, fta.* EXCLUDE (ACCOUNT_ID), ft.* EXCLUDE (ACCOUNT_ID), zi.FOUNDED_YEAR
FROM aud LEFT JOIN fta USING (ACCOUNT_ID) LEFT JOIN ft USING (ACCOUNT_ID) LEFT JOIN zi USING (ACCOUNT_ID)"""

PERSONAL_FEATURES_SQL = f"""WITH {_sp_PER_AUD},
fta AS (
  SELECT SFACCOUNTID AS ACCOUNT_ID,
         SUM(IFF(PRODUCT_KIND = 'deposit', BALANCE, NULL)) AS DEPOSIT_BALANCE,
         SUM(IFF(PRODUCT_KIND = 'deposit', DIRECT_DEPOSIT_AMOUNT, NULL)) AS DIRECT_DEPOSIT,
         COUNT(DISTINCT FINANCIAL_ACCOUNT_TYPE) AS PRODUCT_COUNT, MIN(OPEN_DATE) AS FIRST_OPEN_DATE,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Loans' AND PRODUCT_KIND = 'loan', 1, 0)) AS HAS_LOAN,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Loans' AND PRODUCT_KIND = 'line', 1, 0)) AS HAS_LINE,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Credit Cards', 1, 0)) AS HAS_CARD,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Treasury Management', 1, 0)) AS HAS_TREASURY,
         MAX(IFF(FINANCIAL_ACCOUNT_TYPE = 'Investments', 1, 0)) AS HAS_INVESTMENT
  FROM {_sp_PREFIX}.FINANCIAL_TRANSACTION_ACCOUNTS
  WHERE COALESCE(ACTIVE, TRUE) GROUP BY 1
),
ftm AS (
  SELECT SFACCOUNTID AS ACCOUNT_ID, FLOOR(DATEDIFF(day, TRANSACTIONDATE, {_sp_FEED_ANCHOR}) / 30) AS b,
         SUM(IFF(TRANSACTION_TYPE = 'Credit', AMOUNT, 0)) AS cr
  FROM {_sp_PREFIX}.FINANCIAL_TRANSACTIONS
  WHERE {_sp_FEED_WINDOW} GROUP BY 1, 2
),
ft AS (
  SELECT ACCOUNT_ID, AVG(cr) AS MONTHLY_CREDITS FROM ftm WHERE b < 3 GROUP BY 1
),
cl AS (
  SELECT ACCOUNT_ID, MAX(IS_OWNER) AS IS_OWNER, MAX(OUTSTANDING_MORTGAGE_BALANCE) AS MORTGAGE_BALANCE,
         MAX(ESTIMATED_PROPERTY_VALUE) AS PROPERTY_VALUE
  FROM {_sp_PREFIX}.CORELOGIC_PROPERTY
  WHERE PROFILE_QUARTER = (SELECT MAX(PROFILE_QUARTER) FROM {_sp_PREFIX}.CORELOGIC_PROPERTY) GROUP BY 1
),
cd AS (
  SELECT ACCOUNT_ID, MAX(LIFE_STAGE) AS LIFE_STAGE, MAX(INVESTMENT_PROPENSITY_SCORE) AS INVESTMENT_PROPENSITY,
         MAX(FINANCIAL_STRESS_INDICATOR) AS FINANCIAL_STRESS
  FROM {_sp_PREFIX}.CLARITAS_DEMOGRAPHICS
  WHERE PROFILE_MONTH = (SELECT MAX(PROFILE_MONTH) FROM {_sp_PREFIX}.CLARITAS_DEMOGRAPHICS) GROUP BY 1
)
SELECT aud.*, fta.* EXCLUDE (ACCOUNT_ID), ft.* EXCLUDE (ACCOUNT_ID),
       cl.* EXCLUDE (ACCOUNT_ID), cd.* EXCLUDE (ACCOUNT_ID)
FROM aud LEFT JOIN fta USING (ACCOUNT_ID) LEFT JOIN ft USING (ACCOUNT_ID)
     LEFT JOIN cl USING (ACCOUNT_ID) LEFT JOIN cd USING (ACCOUNT_ID)"""


def _sp_to_dict(row) -> dict:
    """Snowpark Row -> plain dict (dicts pass through)."""
    if isinstance(row, dict):
        return row
    if hasattr(row, "asDict"):
        return dict(row.asDict())
    return dict(row)


def dedupe_anchors(rows: list[dict]) -> list[dict]:
    """Python backstop on ACCOUNT_ID: keep the first row per account."""
    seen: set = set()
    out = []
    for r in rows:
        k = r["ACCOUNT_ID"]
        if k in seen:
            continue
        seen.add(k)
        out.append(r)
    return out


def _sp_stage(session, table: str, columns: tuple[str, ...], rows: list[dict]) -> str:
    """write_pandas into <table>_STAGING (DDL: must run before BEGIN). Returns the staging name."""
    import pandas as pd

    staging = table + "_STAGING"
    session.write_pandas(
        pd.DataFrame(rows, columns=list(columns)), staging.split(".")[-1], database=_sp_DB, schema=_sp_SCHEMA,
        auto_create_table=True, overwrite=True,
    )
    return staging


def replace_tables(session, writes, check=None) -> int:
    """All-or-nothing replace of every target: stage all, then one BEGIN; DELETE + INSERT...SELECT
    per table; optional check(session) inside the transaction; COMMIT. ROLLBACK on any error.
    writes: [(table, columns, rows), ...]. Staging tables are dropped in finally, best-effort."""
    staged: list[str] = []
    try:
        for table, columns, rows in writes:
            staged.append(table + "_STAGING")
            _sp_stage(session, table, columns, rows)
        session.sql("BEGIN").collect()
        try:
            for table, columns, _ in writes:
                cols = ", ".join(columns)
                session.sql(f"DELETE FROM {table}").collect()
                session.sql(f"INSERT INTO {table} ({cols}) SELECT {cols} FROM {table}_STAGING").collect()
            if check is not None:
                check(session)
            session.sql("COMMIT").collect()
        except Exception:
            try:
                session.sql("ROLLBACK").collect()
            except Exception:
                pass  # never mask the original failure
            raise
    finally:
        for staging in staged:
            try:
                session.sql(f"DROP TABLE IF EXISTS {staging}").collect()
            except Exception:
                pass  # cleanup must not mask the original failure
    return sum(len(rows) for _, _, rows in writes)


def _sp_scalar(session, sql: str) -> int:
    return int(session.sql(sql).collect()[0][0] or 0)


def assert_inputs(session) -> None:
    """Coverage, uniqueness, disjointness, key-prefix and audience-size checks on both subsets."""
    sides = (
        ("business", _sp_BIZ_AUD, _sp_BIZ_SUBSET),
        ("personal", _sp_PER_AUD, _sp_PER_SUBSET),
    )
    for side, aud, subset in sides:
        expected_sql = f"WITH {aud} SELECT COUNT(*) FROM aud"
        assert_coverage(session, expected_sql, f"SELECT COUNT(DISTINCT ACCOUNTID) FROM {subset}")
        dups = _sp_scalar(session, f"SELECT COUNT(*) - COUNT(DISTINCT ACCOUNTID) FROM {subset}")
        if dups:
            raise RuntimeError(f"coverage gap: {side} subset has {dups} duplicate ACCOUNTID rows")
        bad = _sp_scalar(session, f"SELECT COUNT(*) FROM {subset} WHERE ACCOUNTID NOT LIKE '001am%'")
        if bad:
            raise RuntimeError(f"coverage gap: {side} subset has {bad} keys not LIKE '001am%'")
        aud_n = _sp_scalar(session, expected_sql)
        rows_n = _sp_scalar(session, f"SELECT COUNT(*) FROM {subset}")
        if rows_n > aud_n:
            raise RuntimeError(
                f"coverage gap: {side} subset has {rows_n} rows, audience has {aud_n}"
            )
    overlap = _sp_scalar(
        session,
        f"SELECT COUNT(*) FROM {_sp_BIZ_SUBSET} b JOIN {_sp_PER_SUBSET} p ON b.ACCOUNTID = p.ACCOUNTID",
    )
    if overlap:
        raise RuntimeError(f"coverage gap: {overlap} accounts appear in both subsets")


def _sp_build_inputs(rows, profile_fn, input_fn, run_ts):
    """Zero tolerance: returns (input_rows, errors); the caller raises if errors is non-empty."""
    out, errors = [], []
    for r in rows:
        try:
            out.append(input_fn(profile_fn(r, r, run_ts)))
        except Exception as exc:  # noqa: BLE001 - collected and raised by main
            errors.append((r.get("ACCOUNT_ID"), str(exc)[:200]))
    return out, errors


def main(session, mode: str = "INPUTS") -> str:
    mode = (mode or "").upper()
    if mode not in _sp_MODES:
        raise ValueError(f"mode must be one of {_sp_MODES}, got {mode!r}")

    started = datetime.now(timezone.utc).replace(tzinfo=None)
    run_ts = started
    log_id = str(uuid.uuid4())
    status, err = "SUCCEEDED", None
    rows_inserted = accounts_processed = 0
    try:
        biz = dedupe_anchors([_sp_to_dict(r) for r in session.sql(BUSINESS_FEATURES_SQL).collect()])
        per = dedupe_anchors([_sp_to_dict(r) for r in session.sql(PERSONAL_FEATURES_SQL).collect()])
        accounts_processed = len(biz) + len(per)
        if not biz or not per:
            empty = "business" if not biz else "personal"
            raise RuntimeError(f"empty audience: {empty} feature query returned no accounts")

        # Build every DataFrame and pass every gate before any staging or DML.
        writes = []
        if mode in ("INPUTS", "ALL"):
            biz_in, biz_err = _sp_build_inputs(biz, business_profile, business_input_row, run_ts)
            per_in, per_err = _sp_build_inputs(per, personal_profile, personal_input_row, run_ts)
            errors = [("business",) + e for e in biz_err] + [("personal",) + e for e in per_err]
            if errors:
                raise RuntimeError(
                    f"input row factory failed on {len(errors)} accounts; first 3: {errors[:3]}"
                )
            writes += [(_sp_BIZ_SUBSET, BUSINESS_SUBSET_COLUMNS, biz_in),
                       (_sp_PER_SUBSET, PERSONAL_SUBSET_COLUMNS, per_in)]

        if mode in ("TRAINING", "ALL"):
            biz_tr = build_training_set([(r, r) for r in biz], "business", run_ts, _sp_BIZ_TRAINING_SIZE)
            per_tr = build_training_set([(r, r) for r in per], "personal", run_ts, _sp_PER_TRAINING_SIZE)
            for side, tr in (("business", biz_tr), ("personal", per_tr)):
                problems = mix_problems([r["RECOMMENDED_PRODUCT"] for r in tr], floor=100)
                if problems:
                    raise RuntimeError(f"label mix gate: {side}: " + "; ".join(problems))
            writes += [(_sp_BIZ_TRAINING, BUSINESS_TRAINING_COLUMNS, biz_tr),
                       (_sp_PER_TRAINING, PERSONAL_TRAINING_COLUMNS, per_tr)]

        check = assert_inputs if mode in ("INPUTS", "ALL") else None
        rows_inserted = replace_tables(session, writes, check=check)
    except Exception as exc:
        status = "FAILED"
        err = str(exc)[:4000]
        raise
    finally:
        duration_ms = int((datetime.now(timezone.utc).replace(tzinfo=None) - started).total_seconds() * 1000)
        session.sql(
            """
            INSERT INTO DATA_JEDAIS.FINS__PUBLIC.TASK_EXECUTION_LOG
                (LOG_ID, TASK_NAME, EXECUTION_TIME, STATUS, ROWS_INSERTED,
                 ACCOUNTS_PROCESSED, ERROR_MESSAGE, DURATION_MS)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            params=[log_id, f"{TASK_NAME}[{mode}]", started, status, rows_inserted, accounts_processed, err, duration_ms],
        ).collect()

    return f"{TASK_NAME}: {status} rows={rows_inserted} accounts={accounts_processed}"
$$;
